use std::f64::consts::TAU;
use std::path::{Path, PathBuf};

use crate::geometry::{flatten, Rect};
use crate::ground_truth::GroundTruth;
use crate::label_set::LabelSet;
use crate::layout::{is_inside, Layout, Leg};
use crate::map::{Coord, CoordList, Map, Object, ObjectKind, PathObject, Point, Symbol};
use crate::path_builder::coord_at;
use crate::random::Random;
use crate::render::{render_map_over, save_pixmap, Extent, DEFAULT_FRAME, DEFAULT_RESOLUTION};
use crate::renderer::Renderer;
use crate::symbol_kinds::{shows_over, Catalogue, Entry, Overlays};
use crate::xml_reader;
use crate::xml_writer::MapFile;

/// The subfolder of a dataset holding the map files.
pub const MAPS_FOLDER: &str = "maps";

/// The subfolder holding the rendered images, which are a model's input.
pub const IMAGES_FOLDER: &str = "images";

/// The subfolder holding the labels, which are what it is scored against.
pub const GROUND_TRUTH_FOLDER: &str = "gt";

/// The file naming what a label's channels are, written in the dataset's own
/// folder.
pub const CLASSES_FILE: &str = "classes.json";

/// The file saying what density each map was drawn at, written in the
/// dataset's own folder where [`Settings::resolution_range`] makes them
/// differ: a header, then `<name>,<pixels per meter>` for each map.
pub const RESOLUTIONS_FILE: &str = "resolutions.csv";

/// The default number of cells a generated map is across.
pub const DEFAULT_LAYOUT_SIZE: usize = 3;

/// The default width of one cell, in meters on the ground.
pub const DEFAULT_CELL_SIZE: u32 = 150;

/// The default number of maps in a dataset.
pub const DEFAULT_MAPS: usize = 10;

/// The default share of cell sides left without a line on them.
pub const DEFAULT_EMPTY_SIDES: f64 = 0.5;

/// The default chance of a line through the inside of the cells starting in
/// a cell: none, so that a dataset made before there were such lines comes
/// out the same.
pub const DEFAULT_INTERIOR_LINES: f64 = 0.0;

/// How many lines through the inside of the cells may go through one cell:
/// two, one each way across it, as a cell has four sides to cross and no
/// two lines head for the same one.
pub const MAX_LINES_PER_CELL: usize = 2;

/// The chance of a line through the inside of the cells stopping in the
/// cell it has got to, rather than going on into the next.
const INTERIOR_STOP: f64 = 0.35;

/// How far a line through the inside of the cells which stops short of a
/// side gets towards it from the middle of its cell, at the least and at the
/// most, as a share of the way.
const PARTWAY: (f64, f64) = (0.3, 0.7);

/// The default chance of a cell being covered by a transparent area.
pub const DEFAULT_TRANSPARENT_AREAS: f64 = 0.1;

/// The default chance of a cell holding at least one point symbol.
pub const DEFAULT_POINT_SYMBOLS: f64 = 0.5;

/// What a dataset is to be made of.
pub struct Settings {
    /// How many cells a map is across: a map is `layout_size` by
    /// `layout_size` cells.
    pub layout_size: usize,
    /// How wide one cell is, in meters on the ground.
    pub cell_size: u32,
    /// How many maps the folder is to hold.
    pub maps: usize,
    /// Whether the maps must keep to the IOF rules for what may be drawn
    /// where.
    ///
    /// Nothing reads it yet: what goes over a piece of ground is picked for
    /// showing up on it, by [`Overlays`], and not for being a thing a
    /// surveyor would draw there. It is carried here so that a dataset
    /// generated now records the setting it was asked for.
    pub iof_rules: bool,
    /// What the randomness is seeded with. The same seed gives the same
    /// dataset; the n-th map of a dataset is seeded with `seed + n`, so a map
    /// keeps its shape however many maps are asked for.
    pub seed: u64,
    /// The share of cell sides left without a line drawn along them, from 0
    /// for a line on every side to 1 for none at all. Each side is decided
    /// on its own, so this is what comes out on average rather than a count.
    pub empty_sides: f64,
    /// The chance of a line running through the inside of the cells, rather
    /// than along their sides, starting in a cell: each cell has
    /// [`MAX_LINES_PER_CELL`] tries at it, each decided on its own.
    ///
    /// A line along a side is always where one piece of ground meets the
    /// next, which a network can learn to read as "a line is where the
    /// ground changes"; a path through a forest or a stream across open land
    /// is not. Such a line goes from near the middle of its cell through
    /// near the middle of a side into the next cell, and on from cell to
    /// cell until it stops (in a cell, or partway to a side it may not
    /// cross) or runs off the map. It only goes through cells it shows up
    /// over and whose ground draws no border, and through at most
    /// [`MAX_LINES_PER_CELL`] of them a cell. No two head for the same side
    /// of a cell, so two in one cell cross or pass each other, and never
    /// run along each other. Nought, the default, draws none and leaves the
    /// dice as they were.
    pub interior_lines: f64,
    /// The chance of a cell being covered by a transparent area, decided
    /// cell by cell.
    pub transparent_areas: f64,
    /// The chance of a cell holding at least one point symbol. Two are half
    /// as likely as one, three half as likely again, and so on — see
    /// [`Random::halving_count`].
    pub point_symbols: f64,
    /// Whether to stop after the ground: the opaque areas which fill the
    /// cells are drawn and the three steps over them — the lines, the
    /// see-through areas and the point symbols — are skipped, whatever
    /// [`Settings::empty_sides`], [`Settings::transparent_areas`] and
    /// [`Settings::point_symbols`] say.
    ///
    /// The labels in `gt/` are written only where this is on: a pixel's
    /// answer is the one piece of ground cover under it, and there is no such
    /// answer for a pixel a line or a point symbol was drawn over.
    pub just_opaque_areas: bool,
    /// Whether the lines along the cell sides are labelled, as a second
    /// layer over the ground: see [`crate::line_truth`].
    ///
    /// The ground keeps its own label under a line, so a map with lines is
    /// answerable as long as nothing else is drawn over it: this needs
    /// [`Settings::transparent_areas`] and [`Settings::point_symbols`] at
    /// nought, and is refused otherwise, since those would be drawn and not
    /// labelled. With it on, `classes.json` also names the line symbols, and
    /// the labels of the lines are rebuilt from `maps/` where they are
    /// wanted rather than kept in a folder of their own.
    pub line_labels: bool,
    /// Whether the point symbols are labelled too, as a third layer: see
    /// [`crate::point_truth`].
    ///
    /// Like the lines' layer, it is rebuilt from `maps/` rather than written
    /// down, and it needs [`Settings::line_labels`] on — the lines are drawn
    /// whether or not they are labelled — and [`Settings::transparent_areas`]
    /// at nought, which nothing labels yet. With it on, `classes.json` also
    /// names the point symbols.
    pub point_labels: bool,
    /// Whether to draw each map to an image, and to label that image.
    ///
    /// Drawing is most of the work of generating a dataset — a default map is
    /// two and a half million pixels — so turning it off is what somebody
    /// after the maps alone wants. Without an image there is nothing for a
    /// label to be a label of, so `gt/` goes with it.
    pub images: bool,
    /// Whether to write the labels in `gt/`, where [`Settings::images`] and
    /// [`Settings::just_opaque_areas`] would otherwise have them written.
    ///
    /// Off is for somebody after the maps and their images alone, with no use
    /// for the answers on disk. `classes.json` is written regardless: it is
    /// what lets a label be computed from `maps/` instead of read from
    /// `gt/`, which is the one thing a folder without `gt/` still needs from
    /// the dataset to be trained on.
    pub ground_truth: bool,
    /// How many pixels of image one meter of ground comes to, which is what
    /// decides how big the images and their labels are.
    ///
    /// Where [`Settings::resolution_range`] is set, this is the dataset's
    /// *normal* density rather than every map's: the images are still the
    /// size the layout and the frame come to at this resolution, and each map
    /// is drawn at a density of its own — see [`Settings::sheet`].
    pub resolution: f64,
    /// The densities the maps are drawn at, lowest and highest, in pixels per
    /// meter of ground; `None` draws every map at [`Settings::resolution`].
    ///
    /// Each map's is drawn log-uniformly from the range (so a map at half the
    /// normal density is as likely as one at twice it), and the image stays
    /// the same number of pixels: what changes is how much ground it shows.
    /// The layout and the frame are scaled with the ground, so a cell is as
    /// many pixels across at every density, and the only thing in a picture
    /// which says how dense it is, is the symbols — the widths of the lines,
    /// the sizes of the dots and of the patterns, which a symbol set fixes on
    /// the paper. That is what a network is to learn the density from, and
    /// nothing in the layout is left for it to cheat with.
    ///
    /// Each map's density is written to [`RESOLUTIONS_FILE`].
    pub resolution_range: Option<(f64, f64)>,
    /// How much white ground to leave around the square a map covers, in
    /// meters. Part of the image and part of the labels, where it is the
    /// background class.
    pub frame: f64,
}

impl Default for Settings {
    fn default() -> Settings {
        Settings {
            layout_size: DEFAULT_LAYOUT_SIZE,
            cell_size: DEFAULT_CELL_SIZE,
            maps: DEFAULT_MAPS,
            iof_rules: false,
            seed: 0,
            empty_sides: DEFAULT_EMPTY_SIDES,
            interior_lines: DEFAULT_INTERIOR_LINES,
            transparent_areas: DEFAULT_TRANSPARENT_AREAS,
            point_symbols: DEFAULT_POINT_SYMBOLS,
            just_opaque_areas: false,
            line_labels: false,
            point_labels: false,
            images: true,
            ground_truth: true,
            resolution: DEFAULT_RESOLUTION,
            resolution_range: None,
            frame: DEFAULT_FRAME,
        }
    }
}

/// How one map of a dataset is laid out and drawn: the density it is drawn
/// at, and the ground its picture covers.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Sheet {
    /// How many pixels of image one meter of ground comes to.
    pub resolution: f64,
    /// How much bigger, on the ground, this map's layout and frame are than
    /// the [`Settings`] say: one at the normal density, two at half of it.
    pub stretch: f64,
    /// The square of ground the image covers, centred on the origin.
    pub ground: Rect,
}

impl Settings {
    /// The square of ground every image of the dataset covers: the layout,
    /// which is centred on the origin, with the frame around it.
    ///
    /// Known before a map is generated, and the same for all of them, which
    /// is what makes the images of one dataset one size.
    pub fn ground(&self) -> Rect {
        let half = (self.layout_size * self.cell_size as usize) as f64 / 2.0 + self.frame;
        Rect::from_ltrb(-half, -half, half, half)
    }

    /// How many pixels across an image of this dataset comes out, which is
    /// also how many labels one holds per row.
    pub fn image_size(&self) -> u32 {
        (self.ground().width() * self.resolution).round().max(0.0) as u32
    }

    /// Whether the maps are drawn at densities of their own rather than all
    /// at [`Settings::resolution`].
    pub fn varies(&self) -> bool {
        self.resolution_range.is_some_and(|(low, high)| low < high)
    }

    /// How the `index`-th map is drawn: at [`Settings::resolution`] over
    /// [`Settings::ground`], or — where the density varies — at one drawn
    /// out of the range, over as much ground as the same number of pixels
    /// covers at it.
    ///
    /// The density comes out of a generator of its own, seeded by the map's
    /// index, so a map's density does not move the dice its shapes are drawn
    /// with, and the n-th map has the same density however many are asked
    /// for.
    pub fn sheet(&self, index: usize) -> Sheet {
        let normal = Sheet {
            resolution: self.resolution,
            stretch: 1.0,
            ground: self.ground(),
        };
        let Some((low, high)) = self.resolution_range.filter(|_| self.varies()) else {
            return normal;
        };

        // Log-uniform: as likely to halve the density as to double it.
        let mut random = Random::from_seed(self.seed.wrapping_add(index as u64) ^ RESOLUTION_SEED);
        let resolution = random.between(low.ln(), high.ln()).exp();

        // The image is the size it is at the normal density, and covers that
        // many pixels' worth of ground at this one: worked out from the
        // pixels rather than by scaling the ground, so that rounding never
        // makes one map of a dataset a pixel bigger than the rest.
        let pixels = self.image_size() as f64;
        let side = pixels / resolution;
        Sheet {
            resolution,
            stretch: side / self.ground().width(),
            ground: Rect::from_ltrb(-side / 2.0, -side / 2.0, side / 2.0, side / 2.0),
        }
    }
}

/// What the generator a map's density is drawn out of is seeded with, beside
/// the map's own seed: anything, as long as it is not what the map's shapes
/// come out of.
const RESOLUTION_SEED: u64 = 0x5ca1_ab1e_d0e5_1717;

/// How many objects of each sort a whole dataset came to.
#[derive(Debug, Default)]
pub struct Drawn {
    /// The cell fills: one per cell of every map.
    pub fills: usize,
    /// The lines along cell sides.
    pub lines: usize,
    /// The lines through the inside of the cells — see
    /// [`Settings::interior_lines`].
    pub interior_lines: usize,
    /// The transparent areas laid over a cell.
    pub transparent_areas: usize,
    /// The point symbols dropped into a cell.
    pub points: usize,
    /// The point symbols a cell was dealt and had no room for: every place
    /// tried was on a line or on another point — see [`LINE_GAP`].
    pub crowded: usize,
}

/// The files one generated map came to.
pub struct Generated {
    /// The map itself, in `maps/`.
    pub map: PathBuf,
    /// The image it was rendered to, in `images/`. Absent where
    /// [`Settings::images`] is off.
    pub image: Option<PathBuf>,
    /// The labels for that image, in `gt/`. Absent unless there is an image
    /// and [`Settings::just_opaque_areas`] is on, since nothing else has an
    /// answer to write down yet.
    pub ground_truth: Option<PathBuf>,
}

/// What a run came to.
pub struct Summary {
    /// The maps written, in the order they were generated.
    pub written: Vec<Generated>,
    /// The symbols the maps were built from, sorted into kinds: the set's,
    /// less those its table of labels says are only ever drawn as parts of
    /// others.
    pub catalogue: Catalogue,
    /// What a network is told about the maps: the classes their labels are
    /// in, and how each symbol is labelled with them.
    pub labels: LabelSet,
    /// What of that set may be drawn over what, which is what the generator
    /// picked its overlays out of.
    pub overlays: Overlays,
    /// How much of each sort of object the dataset came to.
    pub drawn: Drawn,
    /// The scale of the source map, which every generated map inherits.
    pub scale_denominator: i32,
    /// How many pixels across every image of the dataset came out.
    pub image_size: u32,
    /// Where the symbol set was copied to, which is the dataset's own folder
    /// and the source's own file name.
    pub symbol_set: PathBuf,
    /// Complaints from reading the source map, and from drawing the maps
    /// which came out of it.
    pub warnings: Vec<String>,
}

/// A folder of random maps built on the symbol set of `source`, written into
/// `into` — the maps, the images they render to and the labels for those
/// images, in the three subfolders this module describes.
///
/// The symbol set itself is copied in beside them, under its own file name.
/// A class of a label is a place in the list of that set's opaque areas and
/// nothing else says which place, so a dataset without the set is a folder of
/// answers to a question nobody kept: see [`copy_symbol_set`].
///
/// `into` and its subfolders are created if they are not there, and a file of
/// a previous run under the same name is overwritten.
pub fn create_dataset(
    source: &Path,
    into: &Path,
    settings: &Settings,
    mut progress: impl FnMut(usize, usize),
) -> Result<Summary, String> {
    if settings.layout_size == 0 {
        return Err("the layout size must be at least one cell".to_string());
    }
    if settings.cell_size == 0 {
        return Err("the cell size must be at least one meter".to_string());
    }
    if settings.resolution.is_nan() || settings.resolution <= 0.0 {
        return Err(format!(
            "the resolution must be more than zero pixels per meter, not {}",
            settings.resolution
        ));
    }
    if let Some((low, high)) = settings.resolution_range {
        if !(low.is_finite() && high.is_finite() && 0.0 < low && low <= high) {
            return Err(format!(
                "the resolutions run from more than nothing to no less than that, not from {low} \
                 to {high} pixels per meter"
            ));
        }
        if !(low..=high).contains(&settings.resolution) {
            return Err(format!(
                "the resolution, {} pixels per meter, is the density the images are sized at and \
                 has to lie in the range the maps are drawn at, {low} to {high}",
                settings.resolution
            ));
        }
    }
    if settings.frame.is_nan() || settings.frame < 0.0 {
        return Err(format!(
            "the frame cannot be less than nothing, and is {} meters",
            settings.frame
        ));
    }
    if settings.image_size() == 0 {
        return Err(format!(
            "{} meters of ground at {} pixels per meter is no image at all",
            settings.ground().width(),
            settings.resolution
        ));
    }
    for (share, name) in [
        (settings.empty_sides, "the share of sides left empty"),
        (
            settings.interior_lines,
            "the chance of a line through the cells",
        ),
        (
            settings.transparent_areas,
            "the chance of a transparent area",
        ),
        (settings.point_symbols, "the chance of a point symbol"),
    ] {
        if !(0.0..=1.0).contains(&share) {
            return Err(format!("{name} must be between zero and one, not {share}"));
        }
    }

    if settings.point_labels && !settings.just_opaque_areas {
        if !settings.line_labels {
            return Err(
                "point labels need the line labels too: the lines are drawn either way, and \
                 would be left unlabelled"
                    .to_string(),
            );
        }
        if settings.transparent_areas > 0.0 {
            return Err(
                "point labels need the transparent areas at nought: they would be drawn over \
                 the ground and left unlabelled"
                    .to_string(),
            );
        }
    }
    if settings.line_labels
        && !settings.point_labels
        && !settings.just_opaque_areas
        && (settings.transparent_areas > 0.0 || settings.point_symbols > 0.0)
    {
        return Err(
            "line labels need the transparent areas and the point symbols at nought: they \
             would be drawn over the ground and left unlabelled"
                .to_string(),
        );
    }
    let (mut map, warnings) = xml_reader::read_xml_map(source)?;
    map.resolve_references();
    let fragments = xml_reader::read_fragments(source)?;

    // What a network is told about these maps: a class per symbol, or what
    // the table beside the set says -- and, where there is a table, the
    // symbols it gives no parts to are only ever parts of others, and are
    // not drawn on their own.
    let labels = LabelSet::beside(&map, source)?;
    let mut catalogue = Catalogue::of(&map);
    catalogue.retain(|entry| labels.drawn(entry.index));
    if catalogue.opaque_areas.is_empty() {
        return Err(format!(
            "{} holds no opaque area symbol, so there is nothing to fill a cell with",
            source.display()
        ));
    }
    // Step one, the rest of it: what of this set may be drawn over what.
    let overlays = Overlays::of(&map, &catalogue);

    // Only a map of nothing but ground cover has an answer, and only an
    // image has anything for that answer to be about; a folder missing
    // either has nothing classes.json could describe, whatever
    // Settings::ground_truth says. Where there is an answer, classes.json
    // goes out regardless of ground_truth: it is what lets training compute
    // a map's labels from maps/ itself, the one thing a folder without gt/
    // still needs from the dataset.
    let answerable = settings.images
        && (settings.just_opaque_areas || settings.line_labels || settings.point_labels);
    let labelled = answerable && settings.ground_truth;

    let (maps_folder, images_folder, gt_folder) = (
        into.join(MAPS_FOLDER),
        into.join(IMAGES_FOLDER),
        into.join(GROUND_TRUTH_FOLDER),
    );
    for folder in [
        Some(&maps_folder),
        settings.images.then_some(&images_folder),
        labelled.then_some(&gt_folder),
    ]
    .into_iter()
    .flatten()
    {
        std::fs::create_dir_all(folder)
            .map_err(|e| format!("cannot make {}: {e}", folder.display()))?;
    }

    // The set the maps are drawn with, beside the maps. Whatever else this
    // folder is for, a label in it means nothing without the list of symbols
    // its classes are places in.
    let symbol_set = copy_symbol_set(source, into)?;
    // And the table its classes come out of, under its own name beside it,
    // where there is one: the classes of a label are places in that.
    let table = match &labels.table {
        Some(table) => Some(copy_symbol_set(table, into)?),
        None => None,
    };
    if answerable {
        let classes = Catalogue {
            opaque_areas: labels.areas.clone(),
            lines: labels.lines.clone(),
            points: labels.points.clone(),
            ..Catalogue::default()
        };
        write_classes(
            &into.join(CLASSES_FILE),
            &classes,
            table.as_deref(),
            settings,
            &symbol_set,
        )?;
    }

    let generator = Generator {
        map: &map,
        catalogue: &catalogue,
        overlays: &overlays,
        labels: &labels,
        lines_over: lines_over(&map, &catalogue),
        bordered: catalogue
            .opaque_areas
            .iter()
            .map(|area| {
                labels.outline_half_width(&map, area.index) > 0.0
                    || draws_a_border(&map, &map.symbols[area.index], 0)
            })
            .collect(),
        settings,
        // Map coordinates are in mm on the paper; a layout is in meters on
        // the ground.
        mm_per_meter: 1000.0 / map.scale_denominator as f64,
        point_radii: catalogue
            .points
            .iter()
            .map(|point| point_radius(&map, point))
            .collect(),
        line_half_widths: catalogue
            .lines
            .iter()
            .map(|line| line_half_width(&map, line))
            .collect(),
    };

    let mut written = Vec::with_capacity(settings.maps);
    let mut drawn = Drawn::default();
    let mut warnings = warnings;
    // Each map's density, where they differ, as the file says it.
    let mut resolutions = String::from("map,resolution\n");
    for index in 0..settings.maps {
        // A seed of its own per map, so that the third map of a dataset is
        // the same map whether ten or a thousand were asked for.
        let mut random = Random::from_seed(settings.seed.wrapping_add(index as u64));
        let sheet = settings.sheet(index);
        // The cells stretched with the ground, so that they are as many
        // pixels across at every density: see `Settings::resolution_range`.
        let layout = Layout::random(
            settings.layout_size,
            settings.cell_size as f64 * sheet.stretch,
            &mut random,
        );
        let objects = generator.draw(&layout, &mut random, &mut drawn);

        let stem = map_stem(index, settings.maps);
        // `{}` of an f64 is the shortest text which reads back as the same
        // number, which is what a label rebuilt from the map has to land on
        // the image's own pixel grid with.
        resolutions.push_str(&format!("{stem},{}\n", sheet.resolution));
        let map_path = maps_folder.join(format!("{stem}.omap"));
        MapFile {
            scale_denominator: map.scale_denominator,
            notes: "",
            georeferencing: None,
            colors: &fragments.colors,
            symbols: &fragments.symbols,
            objects: &objects,
            // An object is given a rotation only where its symbol can use
            // one, so a rotation written here is a rotation something reads.
            rotatable: true,
        }
        .write(&map_path)?;

        let (mut image, mut ground_truth) = (None, None);
        if settings.images {
            // Drawn from the file just written rather than from the objects
            // in hand: the image belongs to the map somebody else can open,
            // and any disagreement between the two is a bug worth tripping
            // over here.
            let drawing =
                render_map_over(&map_path, sheet.resolution, Extent::Ground(sheet.ground))
                    .map_err(|e| format!("cannot draw {}: {e}", map_path.display()))?;
            for warning in drawing.warnings {
                if !warnings.contains(&warning) {
                    warnings.push(warning);
                }
            }

            let path = images_folder.join(format!("{stem}.png"));
            save_pixmap(&drawing.pixmap, &path)
                .map_err(|e| format!("cannot write {}: {e}", path.display()))?;
            image = Some(path);

            if labelled {
                // The same pixel grid the image was drawn on, so a label and
                // the pixel it labels are the same pixel.
                let path = gt_folder.join(format!("{stem}.bin"));
                GroundTruth::rasterize(
                    &labels.grounds(&map, &objects),
                    labels.areas.len(),
                    drawing.pixmap.width(),
                    drawing.pixmap.height(),
                    drawing.page_transform,
                )?
                .write(&path)?;
                ground_truth = Some(path);
            }
        }

        written.push(Generated {
            map: map_path,
            image,
            ground_truth,
        });
        progress(index + 1, settings.maps);
    }

    // Only where the densities differ: a dataset at one density says so in
    // classes.json, and a file of one number repeated would be a second
    // place for it to be wrong. A stale one from an earlier run into the
    // same folder would be read as this run's, so it goes.
    let resolutions_file = into.join(RESOLUTIONS_FILE);
    if settings.varies() {
        std::fs::write(&resolutions_file, resolutions)
            .map_err(|e| format!("cannot write {}: {e}", resolutions_file.display()))?;
    } else if resolutions_file.is_file() {
        std::fs::remove_file(&resolutions_file)
            .map_err(|e| format!("cannot remove {}: {e}", resolutions_file.display()))?;
    }

    Ok(Summary {
        written,
        catalogue,
        labels,
        overlays,
        drawn,
        scale_denominator: map.scale_denominator,
        image_size: settings.image_size(),
        symbol_set: into.join(&symbol_set),
        warnings,
    })
}

/// Copies the symbol set a dataset was generated from into the dataset,
/// under its own file name, and says what that name is.
///
/// A class of a label is a place in the list of the set's opaque areas, and
/// nothing in a labels file says which set that was. Anything reading the
/// answers back — turning them into a map again, saying which symbol a
/// channel is — needs the set, so it travels with them rather than being
/// remembered by whoever ran the generator.
///
/// A source which is already the file it would be copied to is left alone,
/// which is what a second run into the same folder does.
pub fn copy_symbol_set(source: &Path, into: &Path) -> Result<String, String> {
    let name = source
        .file_name()
        .ok_or_else(|| format!("{} is not a file to copy", source.display()))?;
    let copy = into.join(name);
    // Not `source == copy`: the same file reached by two different paths is
    // still the same file, and copying one onto itself truncates it.
    let same = std::fs::canonicalize(source)
        .ok()
        .zip(std::fs::canonicalize(&copy).ok())
        .is_some_and(|(source, copy)| source == copy);
    if !same {
        std::fs::copy(source, &copy).map_err(|e| {
            format!(
                "cannot copy {} to {}: {e}",
                source.display(),
                copy.display()
            )
        })?;
    }
    Ok(name.to_string_lossy().into_owned())
}

/// The symbol set as the generator uses it, and how much of it to use.
struct Generator<'a> {
    /// The set itself, which the symbols are looked up in.
    map: &'a Map,
    catalogue: &'a Catalogue,
    overlays: &'a Overlays,
    labels: &'a LabelSet,
    /// For each opaque area, the lines which show up over it, as places in
    /// [`Catalogue::lines`] — see [`lines_over`].
    lines_over: Vec<Vec<usize>>,
    /// For each opaque area, whether it draws a border round itself — a
    /// building's black outline, a lake's blue one — in the order of
    /// [`Catalogue::opaque_areas`]: see [`draws_a_border`]. No line is drawn
    /// along a side of such a cell, nor through it.
    bordered: Vec<bool>,
    settings: &'a Settings,
    /// How many mm on the paper one meter on the ground is.
    mm_per_meter: f64,
    /// How far each point symbol reaches from its coordinate, in mm on the
    /// paper, in the order of [`Catalogue::points`] — see [`point_radius`].
    point_radii: Vec<f64>,
    /// How far each line symbol reaches from the middle of its path, in mm,
    /// in the order of [`Catalogue::lines`] — see [`line_half_width`].
    line_half_widths: Vec<f64>,
}

impl Generator<'_> {
    /// Everything one map is drawn out of, in the four steps which put it
    /// there: the ground, the lines along the boundaries, the see-through
    /// areas over the ground, and the point symbols scattered on it. Only the
    /// first of them where [`Settings::just_opaque_areas`] is on.
    ///
    /// The labels are not decided here: they are what the objects come to
    /// under the [`LabelSet`], worked out from the objects wherever they are
    /// wanted, so that a label rebuilt from the map file and one written at
    /// generation time are the same label.
    fn draw(&self, layout: &Layout, random: &mut Random, drawn: &mut Drawn) -> Vec<Object> {
        let outlines = layout.cell_outlines(self.mm_per_meter);
        let mut objects = Vec::with_capacity(outlines.len());

        // The ground. The draws are independent, so two cells side by side
        // are sometimes the same ground cover; the shape of the layout is
        // still there, in the boundaries which do show. Each cell's fill is
        // kept as its place in the catalogue, which is what the overlays are
        // listed by.
        let fills: Vec<usize> = outlines
            .iter()
            .map(|outline| {
                let at = random.below(self.catalogue.opaque_areas.len());
                let fill = &self.catalogue.opaque_areas[at];
                objects.push(self.area_object(fill, outline.clone(), random));
                drawn.fills += 1;
                at
            })
            .collect();

        // The ground on its own, where that is all which was asked for: a
        // patchwork of the set's opaque areas, with nothing drawn over it.
        if self.settings.just_opaque_areas {
            return objects;
        }

        // What the point symbols are kept off: the lines, and the outline a
        // cell is labelled with where its symbol draws one round it -- a
        // building's, a lake's.
        let mut taken = Taken::default();
        for (cell, &at) in fills.iter().enumerate() {
            let half = self
                .labels
                .outline_half_width(self.map, self.catalogue.opaque_areas[at].index);
            if half > 0.0 {
                taken.add_line(&outlines[cell], half);
            }
        }

        // A line along some of the cell sides. A side belongs to two cells
        // at once and is drawn once, so what runs along it is the boundary
        // itself rather than one cell's idea of it -- and what runs along it
        // is picked out of the lines which show up over both of them, since
        // a line drawn in the ink of the ground beside it is a line nobody
        // can see, and a label of one is a label of nothing.
        //
        // Nor is a line drawn along a side of a cell whose ground draws a
        // border round itself: it would lie on that border, often in the
        // same ink and as wide, and be labelled as both of them where the
        // picture shows one stroke.
        if !self.catalogue.lines.is_empty() {
            let sides = layout.side_paths(self.mm_per_meter);
            for (side, cells) in sides.into_iter().zip(layout.side_cells()) {
                if random.chance(self.settings.empty_sides) {
                    continue;
                }
                if cells
                    .iter()
                    .flatten()
                    .any(|&cell| self.bordered[fills[cell]])
                {
                    continue;
                }
                let visible: Vec<usize> = (0..self.catalogue.lines.len())
                    .filter(|line| {
                        cells
                            .iter()
                            .flatten()
                            .all(|&cell| self.lines_over[fills[cell]].contains(line))
                    })
                    .collect();
                let Some(&at) = random.pick(&visible) else {
                    continue;
                };
                let line = &self.catalogue.lines[at];
                taken.add_line(&side, self.line_half_widths[at]);
                let mut object = Object::new(ObjectKind::Path(PathObject::default()));
                object.coords = side;
                drawn_with(&mut object, line);
                objects.push(object);
                drawn.lines += 1;
            }
        }

        // Lines through the inside of the cells, which cross the ground
        // rather than following where it changes: see
        // `Settings::interior_lines`. Nothing is drawn from the dice where
        // there are to be none, so a dataset without them comes out as it
        // did before there were any.
        if self.settings.interior_lines > 0.0 && !self.catalogue.lines.is_empty() {
            for (coords, at) in self.interior_lines(layout, &fills, random) {
                taken.add_line(&coords, self.line_half_widths[at]);
                let mut object = Object::new(ObjectKind::Path(PathObject::default()));
                object.coords = coords;
                drawn_with(&mut object, &self.catalogue.lines[at]);
                objects.push(object);
                drawn.interior_lines += 1;
            }
        }

        // A see-through area over some of the cells, picked out of the ones
        // which show up over that cell's ground rather than out of all of
        // them.
        for (cell, &at) in fills.iter().enumerate() {
            if !random.chance(self.settings.transparent_areas) {
                continue;
            }
            let Some(&over) = random.pick(&self.overlays.transparent_areas[at]) else {
                continue;
            };
            let overlay = &self.catalogue.transparent_areas[over];
            objects.push(self.area_object(overlay, outlines[cell].clone(), random));
            drawn.transparent_areas += 1;
        }

        // Point symbols dropped into the cells, however many the halving
        // count gives each of them. One near a boundary draws over it, which
        // is a thing a renderer has to get right and a surveyor draws every
        // day; one on a line or on another point symbol is not, and leaves a
        // pixel with two answers, so those are kept apart -- see `place`.
        for (cell, &at) in fills.iter().enumerate() {
            let polygon: Vec<Point> = flatten(&outlines[cell])
                .into_iter()
                .next()
                .map(|part| part.points)
                .unwrap_or_default();
            for _ in 0..random.halving_count(self.settings.point_symbols) {
                let Some(&over) = random.pick(&self.overlays.points[at]) else {
                    break;
                };
                let point = &self.catalogue.points[over];
                let radius = self.point_radii[over];
                let Some(coord) = place(&polygon, radius, &taken, random) else {
                    drawn.crowded += 1;
                    continue;
                };
                taken.points.push((Point::new(coord.x, coord.y), radius));
                let mut object = Object::new(ObjectKind::Point);
                object.coords = vec![coord];
                if point.turns {
                    object.rotation = random.between(0.0, TAU);
                }
                drawn_with(&mut object, point);
                objects.push(object);
                drawn.points += 1;
            }
        }

        objects
    }

    /// The lines through the inside of the cells of `layout`, filled with
    /// `fills`, each as its path and its place in [`Catalogue::lines`].
    ///
    /// Each cell, in turn, gets [`MAX_LINES_PER_CELL`] tries at starting
    /// one, each with [`Settings::interior_lines`] of a chance, where its
    /// ground draws no border and fewer than that many lines go through it
    /// already. The line's symbol is picked out of the ones which show up
    /// over that ground, and from near the cell's middle it goes out in one
    /// direction and then the other: through near the middle of a side into
    /// the next cell, and on, until it stops in a cell ([`INTERIOR_STOP`]),
    /// runs off the edge of the map, or comes to a cell it may not go into —
    /// one it would not show up over, one whose ground has a border, one it
    /// has been through already or one which has its fill of lines — which
    /// it stops partway to instead ([`PARTWAY`]). The first step of the
    /// first direction never stops, so every line goes somewhere.
    ///
    /// What keeps two lines from running along each other is the sides: a
    /// line heads for the middle of a side, to cross it or to stop short of
    /// it, and no side is headed for by two of them. Two lines in one cell
    /// leave it by different sides, so they cross near its middle or pass
    /// each other, and never share a stretch.
    fn interior_lines(
        &self,
        layout: &Layout,
        fills: &[usize],
        random: &mut Random,
    ) -> Vec<(CoordList, usize)> {
        let size = layout.size();
        let neighbours = layout.side_cells();
        let at = |cell: usize| (cell % size, cell / size);
        // How many lines go through each cell, and whether a line has headed
        // for each side yet.
        let mut through = vec![0; fills.len()];
        let mut taken_sides = vec![false; neighbours.len()];
        // The legs drawn in each cell so far, which a leg there may cross
        // but not run along: two lines through a cell pass near its middle.
        let mut cell_legs: Vec<Vec<Leg>> = vec![Vec::new(); fills.len()];
        let mut lines = Vec::new();

        for start in (0..fills.len()).flat_map(|cell| [cell; MAX_LINES_PER_CELL]) {
            if through[start] >= MAX_LINES_PER_CELL || self.bordered[fills[start]] {
                continue;
            }
            if !random.chance(self.settings.interior_lines) {
                continue;
            }
            let Some(&line) = random.pick(&self.lines_over[fills[start]]) else {
                continue;
            };
            let (column, row) = at(start);
            // Every side of the cell headed for already: nowhere to go.
            if layout
                .cell_sides(column, row)
                .iter()
                .all(|&side| taken_sides[side])
            {
                continue;
            }
            through[start] += 1;
            let mut visited = vec![start];
            let middle = layout.near_center(column, row, random);

            // The legs of the line, out from the start cell's middle, one
            // direction and then the other.
            let mut legs: [Vec<Leg>; 2] = Default::default();
            for direction in 0..2 {
                let (mut cell, mut here) = (start, middle);
                loop {
                    let first_step = direction == 0 && legs[0].is_empty();
                    if !first_step && random.chance(INTERIOR_STOP) {
                        break;
                    }
                    let (column, row) = at(cell);
                    let ways: Vec<usize> = layout
                        .cell_sides(column, row)
                        .into_iter()
                        .filter(|&side| !taken_sides[side])
                        .collect();
                    let Some(&side) = random.pick(&ways) else {
                        break;
                    };
                    // Headed for, whatever comes of it: crossed, or stopped
                    // short of, it is this line's.
                    taken_sides[side] = true;
                    let crossing = layout.side_middle(side, random);
                    let next = neighbours[side]
                        .iter()
                        .flatten()
                        .copied()
                        .find(|&c| c != cell);
                    let out = layout.leg(column, row, here, crossing, &cell_legs[cell], random);
                    match (next, out) {
                        // Off the edge of the map.
                        (None, Some(out)) => {
                            cell_legs[cell].push(out.clone());
                            legs[direction].push(out);
                            break;
                        }
                        (Some(next), Some(out))
                            if !visited.contains(&next)
                                && through[next] < MAX_LINES_PER_CELL
                                && !self.bordered[fills[next]]
                                && self.lines_over[fills[next]].contains(&line) =>
                        {
                            let (column, row) = at(next);
                            let middle = layout.near_center(column, row, random);
                            if let Some(into) =
                                layout.leg(column, row, crossing, middle, &cell_legs[next], random)
                            {
                                through[next] += 1;
                                visited.push(next);
                                cell_legs[cell].push(out.clone());
                                cell_legs[next].push(into.clone());
                                legs[direction].extend([out, into]);
                                (cell, here) = (next, middle);
                                continue;
                            }
                        }
                        _ => {}
                    }
                    // A cell it may not go into, or no way to the side
                    // which keeps inside this one: it ends short of it.
                    let share = random.between(PARTWAY.0, PARTWAY.1);
                    let short = here + (crossing - here) * share;
                    if let Some(leg) =
                        layout.leg(column, row, here, short, &cell_legs[cell], random)
                    {
                        cell_legs[cell].push(leg.clone());
                        legs[direction].push(leg);
                    }
                    break;
                }
            }

            let [out, back] = legs;
            let legs: Vec<Leg> = back.iter().rev().map(Leg::reversed).chain(out).collect();
            if !legs.is_empty() {
                lines.push((layout.path_of(&legs, self.mm_per_meter), line));
            }
        }
        lines
    }

    /// A path object drawn with an area symbol, turned to an angle of its own
    /// where the symbol fills with a pattern which turns.
    fn area_object(&self, area: &Entry, coords: CoordList, random: &mut Random) -> Object {
        let mut object = Object::new(ObjectKind::Path(PathObject::default()));
        object.coords = coords;
        drawn_with(&mut object, area);
        if area.turns {
            // A whole turn, not half of one: a pattern of lines repeats
            // every half turn and the renderer folds the angle into that
            // itself, but the point symbols of a dot pattern turn with the
            // object the whole way round.
            let turn = random.between(0.0, TAU);
            // A path object has one rotation, which is the rotation of its
            // fill pattern, and a file carries it twice: once as the
            // object's attribute and once on its `<pattern>`.
            object.rotation = turn;
            if let ObjectKind::Path(path) = &mut object.kind {
                path.pattern_rotation = turn;
            }
        }
        object
    }
}

/// Points the object at the symbol it is drawn with, both ways the format
/// names one.
fn drawn_with(object: &mut Object, symbol: &Entry) {
    object.symbol_index = Some(symbol.index);
    object.symbol_id = symbol.id;
}

/// Whether `symbol` draws a line round what it fills: a combined symbol with
/// a line among its parts, which is how a symbol set gives an area a border.
fn draws_a_border(map: &Map, symbol: &Symbol, depth: usize) -> bool {
    match symbol {
        Symbol::Combined(combined) if depth < MAX_BORDER_DEPTH => map
            .parts(combined)
            .into_iter()
            .any(|part| matches!(part, Symbol::Line(_)) || draws_a_border(map, part, depth + 1)),
        _ => false,
    }
}

/// How deep [`draws_a_border`] looks into combined symbols made of combined
/// symbols, against a set which makes one a part of itself.
const MAX_BORDER_DEPTH: usize = 16;

/// For each opaque area of `catalogue`, the lines of it which show up drawn
/// over that ground, as places in [`Catalogue::lines`] — the same question
/// [`Overlays`] answers for the see-through areas and the point symbols, see
/// [`shows_over`]. A strip of green vegetation is drawn under the white of a
/// forest, and a black line over a black boulder is not there to see.
fn lines_over(map: &Map, catalogue: &Catalogue) -> Vec<Vec<usize>> {
    catalogue
        .opaque_areas
        .iter()
        .map(|ground| {
            catalogue
                .lines
                .iter()
                .enumerate()
                .filter(|(_, line)| {
                    shows_over(map, &map.symbols[line.index], &map.symbols[ground.index])
                })
                .map(|(at, _)| at)
                .collect()
        })
        .collect()
}

/// The least gap between a point symbol and a line, in mm on the paper,
/// between the edge of the one and the edge of the other.
///
/// A point symbol on a line is a pixel with two answers, and a picture a
/// surveyor would not draw; one a hair beside a line is both a thing they
/// draw every day and the hardest thing for a network to tell apart from it.
/// So a point is kept off the lines by this much and no more, and
/// [`NEAR_LINE`] of them are put right there.
pub const LINE_GAP: f64 = 0.1;

/// The least gap between two point symbols, edge to edge, in mm.
pub const POINT_GAP: f64 = 0.15;

/// The share of the point symbols put just beside a line, where the cell has
/// one near it: within [`NEAR_BAND`] of the closest they may come.
pub const NEAR_LINE: f64 = 0.5;

/// How far past the closest it may come a point put beside a line is, at the
/// most, in mm.
pub const NEAR_BAND: f64 = 0.6;

/// How many places are tried for a point symbol before the cell is taken to
/// have no room for it.
const PLACEMENT_TRIES: usize = 64;

/// What the point symbols of a map are kept clear of: the lines drawn so far
/// and the points placed so far, in mm on the paper.
#[derive(Default)]
struct Taken {
    /// Each line, flattened, with how far it reaches from its middle.
    lines: Vec<(Vec<Point>, f64)>,
    /// Each point, with how far its symbol reaches.
    points: Vec<(Point, f64)>,
}

impl Taken {
    fn add_line(&mut self, coords: &CoordList, half_width: f64) {
        for part in flatten(coords) {
            if part.points.len() >= 2 {
                self.lines.push((part.points, half_width));
            }
        }
    }

    /// Whether a point symbol reaching `radius` from `at` touches nothing.
    fn clear(&self, at: Point, radius: f64) -> bool {
        self.lines
            .iter()
            .all(|(line, half)| distance_to_polyline(at, line) >= half + radius + LINE_GAP)
            && self
                .points
                .iter()
                .all(|&(other, reach)| (at - other).length() >= reach + radius + POINT_GAP)
    }
}

/// Somewhere in the cell `polygon` for a point symbol reaching `radius`,
/// clear of everything `taken` holds — or `None` where
/// [`PLACEMENT_TRIES`] places all touched something.
///
/// [`NEAR_LINE`] of the time, and where a line runs near the cell, the
/// places tried are just beside a line: on either side of it, as close as
/// [`LINE_GAP`] lets them and up to [`NEAR_BAND`] further. A point drawn
/// anywhere in the cell would come that close to a line once in a great
/// while, and next to a path or a fence is where a surveyor puts a great
/// many of them.
fn place(polygon: &[Point], radius: f64, taken: &Taken, random: &mut Random) -> Option<Coord> {
    if polygon.len() < 3 {
        return None;
    }
    let (left, top, right, bottom) = polygon.iter().fold(
        (f64::MAX, f64::MAX, f64::MIN, f64::MIN),
        |(l, t, r, b), p| (l.min(p.x), t.min(p.y), r.max(p.x), b.max(p.y)),
    );
    let reach = NEAR_BAND + taken.lines.iter().map(|(_, h)| *h).fold(0.0, f64::max) + radius;
    let near: Vec<usize> = (0..taken.lines.len())
        .filter(|&at| {
            taken.lines[at].0.iter().any(|p| {
                p.x >= left - reach
                    && p.x <= right + reach
                    && p.y >= top - reach
                    && p.y <= bottom + reach
            })
        })
        .collect();
    let beside = !near.is_empty() && random.chance(NEAR_LINE);

    for _ in 0..PLACEMENT_TRIES {
        let candidate = if beside {
            let (line, half) = &taken.lines[near[random.below(near.len())]];
            let segment = random.below(line.len() - 1);
            let (from, to) = (line[segment], line[segment + 1]);
            let along = to - from;
            if along.length() <= 0.0 {
                continue;
            }
            let side = if random.chance(0.5) { 1.0 } else { -1.0 };
            let off = half + radius + LINE_GAP + random.between(0.0, NEAR_BAND);
            from + along * random.unit() + along.perp_right_unit() * (side * off)
        } else {
            Point::new(random.between(left, right), random.between(top, bottom))
        };
        if is_inside(polygon, candidate) && taken.clear(candidate, radius) {
            return Some(coord_at(candidate));
        }
    }
    None
}

/// The distance from `at` to the nearest point of `line`.
fn distance_to_polyline(at: Point, line: &[Point]) -> f64 {
    line.windows(2)
        .map(|pair| {
            let (from, to) = (pair[0], pair[1]);
            let along = to - from;
            let length = along.dot(along);
            let t = if length > 0.0 {
                ((at - from).dot(along) / length).clamp(0.0, 1.0)
            } else {
                0.0
            };
            (at - (from + along * t)).length()
        })
        .fold(f64::INFINITY, f64::min)
}

/// How far a point symbol reaches from its coordinate, in mm on the paper,
/// whichever way it is turned: the farthest corner of what it draws.
fn point_radius(map: &Map, point: &Entry) -> f64 {
    let mut object = Object::new(ObjectKind::Point);
    object.coords = vec![Coord::new(0.0, 0.0, 0)];
    drawn_with(&mut object, point);
    let extent = Renderer::object_extent(map, &object);
    if extent.width() <= 0.0 && extent.height() <= 0.0 {
        return 0.0;
    }
    [
        (extent.left(), extent.top()),
        (extent.right(), extent.top()),
        (extent.left(), extent.bottom()),
        (extent.right(), extent.bottom()),
    ]
    .into_iter()
    .map(|(x, y)| x.hypot(y))
    .fold(0.0, f64::max)
}

/// How far a line symbol reaches from the middle of its path, in mm on the
/// paper: half of what a long straight line of it is wide, its mid symbols
/// and its border included.
fn line_half_width(map: &Map, line: &Entry) -> f64 {
    let mut object = Object::new(ObjectKind::Path(PathObject::default()));
    object.coords = vec![Coord::new(0.0, 0.0, 0), Coord::new(50.0, 0.0, 0)];
    drawn_with(&mut object, line);
    let extent = Renderer::object_extent(map, &object);
    if extent.width() <= 0.0 && extent.height() <= 0.0 {
        return 0.0;
    }
    extent.top().abs().max(extent.bottom().abs())
}

/// What the n-th map of a dataset of `total` is called, without a suffix:
/// the name its map, its image and its labels share, zero padded far enough
/// that a folder of them sorts the way they were generated.
pub fn map_stem(index: usize, total: usize) -> String {
    let width = total.max(1).to_string().len().max(3);
    format!("map_{:0width$}", index + 1, width = width)
}

/// The file name of the n-th map of a dataset of `total`.
pub fn map_name(index: usize, total: usize) -> String {
    format!("{}.omap", map_stem(index, total))
}

/// Writes what a label's channels mean: one entry per one-hot channel, in the
/// order the channels run, and the settings the images were drawn at.
///
/// A label is a stack of numbers and nothing in it says which number is the
/// bare rock. This is where that is written down, once for the dataset, since
/// it is the symbol set which decides it rather than any one map.
///
/// `symbol_set` is the name that set was copied in under, so that anything
/// reading this file can find the symbols themselves beside it, and `table`
/// the name its table of labels was copied in under, where the classes are
/// that table's rather than one per symbol — see [`crate::label_set`]. The
/// entries of `catalogue` are the classes, each under the symbol it is
/// written back with.
fn write_classes(
    path: &Path,
    catalogue: &Catalogue,
    table: Option<&str>,
    settings: &Settings,
    symbol_set: &str,
) -> Result<(), String> {
    let classes = catalogue.opaque_areas.len();
    let mut json = String::from("{\n");
    json.push_str("  \"format\": \"MAUROGT2\",\n");
    json.push_str(&format!("  \"symbol_set\": {},\n", quoted(symbol_set)));
    // The table the classes come out of, where they are not one per symbol.
    if let Some(table) = table {
        json.push_str(&format!("  \"labels\": {},\n", quoted(table)));
    }
    json.push_str(&format!("  \"classes\": {classes},\n"));
    json.push_str(&format!("  \"channels\": {},\n", classes + 2));
    // The angle is the last two channels, its sine and then its cosine: an
    // angle has a seam where a whole turn brings it back, and a point on the
    // unit circle has none. The zero vector is no angle at all.
    json.push_str(&format!("  \"sin_channel\": {classes},\n"));
    json.push_str(&format!("  \"cos_channel\": {},\n", classes + 1));
    json.push_str(&format!(
        "  \"background\": {},\n",
        crate::ground_truth::BACKGROUND
    ));
    // The lines are a second layer, a yes-or-no per symbol, and only a
    // dataset generated with their labels has one.
    let lines = if settings.line_labels {
        catalogue.lines.len()
    } else {
        0
    };
    json.push_str(&format!("  \"lines\": {lines},\n"));
    // The point symbols are a third layer, a heatmap per symbol, and only a
    // dataset generated with their labels has one.
    let points = if settings.point_labels {
        catalogue.points.len()
    } else {
        0
    };
    json.push_str(&format!("  \"points\": {points},\n"));
    // Which way each point is turned, as two more channels after the
    // heatmaps: see `crate::point_truth::PointTruth::angles`.
    if points > 0 {
        json.push_str("  \"point_angles\": true,\n");
    }
    json.push_str(&format!("  \"image_size\": {},\n", settings.image_size()));
    json.push_str(&format!("  \"resolution\": {},\n", settings.resolution));
    // The range the maps' own densities were drawn from, only where they
    // differ; each map's is in RESOLUTIONS_FILE.
    if let Some((low, high)) = settings.resolution_range.filter(|_| settings.varies()) {
        json.push_str(&format!("  \"resolution_min\": {low},\n"));
        json.push_str(&format!("  \"resolution_max\": {high},\n"));
    }
    json.push_str(&format!("  \"frame\": {},\n", settings.frame));
    json.push_str(&format!("  \"cell_size\": {},\n", settings.cell_size));
    json.push_str(&format!("  \"layout_size\": {},\n", settings.layout_size));
    json.push_str(&format!("  \"seed\": {},\n", settings.seed));
    json.push_str("  \"symbols\": [\n");
    for (channel, entry) in catalogue.opaque_areas.iter().enumerate() {
        json.push_str(&format!(
            "    {{\"channel\": {}, \"id\": {}, \"code\": {}, \"name\": {}, \"turns\": {}}}",
            channel,
            entry.id,
            quoted(&entry.code),
            quoted(&entry.name),
            entry.turns,
        ));
        json.push_str(if channel + 1 == classes { "\n" } else { ",\n" });
    }
    json.push_str("  ]");
    if lines > 0 {
        json.push_str(",\n  \"line_symbols\": [\n");
        for (channel, entry) in catalogue.lines.iter().enumerate() {
            json.push_str(&format!(
                "    {{\"channel\": {}, \"id\": {}, \"code\": {}, \"name\": {}}}",
                channel,
                entry.id,
                quoted(&entry.code),
                quoted(&entry.name),
            ));
            json.push_str(if channel + 1 == lines { "\n" } else { ",\n" });
        }
        json.push_str("  ]");
    }
    if points > 0 {
        json.push_str(",\n  \"point_symbols\": [\n");
        for (channel, entry) in catalogue.points.iter().enumerate() {
            json.push_str(&format!(
                "    {{\"channel\": {}, \"id\": {}, \"code\": {}, \"name\": {}, \"turns\": {}}}",
                channel,
                entry.id,
                quoted(&entry.code),
                quoted(&entry.name),
                entry.turns,
            ));
            json.push_str(if channel + 1 == points { "\n" } else { ",\n" });
        }
        json.push_str("  ]");
    }
    json.push_str("\n}\n");
    std::fs::write(path, json).map_err(|e| format!("cannot write {}: {e}", path.display()))
}

/// What a dataset's `classes.json` says, for the tools which have to read
/// back what [`create_dataset`] wrote there.
///
/// A run of `train` copies this file into its own folder, and everything
/// downstream of a trained model — which symbol a channel is, how much ground
/// a pixel covers — comes out of it. The symbol names are left in the file
/// rather than read here: what wants them wants the symbol set beside it in
/// any case, and [`crate::symbol_kinds::Catalogue`] takes them out of that in
/// the very order this file records.
#[derive(Debug)]
pub struct Classes {
    /// How many one-hot channels a label has: the opaque areas of the set.
    pub classes: usize,
    /// How many line symbols the lines layer has a channel for, or nought for
    /// a dataset with no labels for its lines — see [`crate::line_truth`].
    pub lines: usize,
    /// How many point symbols the points layer has a heatmap for, or nought
    /// for a dataset with no labels for its points — see
    /// [`crate::point_truth`].
    pub points: usize,
    /// How many pixels across the images of the dataset were drawn.
    pub image_size: u32,
    /// How many pixels of image one meter of ground came to: every map's, or
    /// — where [`Classes::resolution_range`] is set — the normal density the
    /// images were sized at, which is what a network trained on them reads
    /// best and what a picture is resampled to before it is read.
    pub resolution: f64,
    /// The range each map's own density was drawn from, lowest first, where
    /// they differ — see [`Settings::resolution_range`] — and `None` where
    /// every map was drawn at [`Classes::resolution`].
    pub resolution_range: Option<(f64, f64)>,
    /// How much white ground was left around each map, in meters, at the
    /// normal density.
    pub frame: f64,
    /// How wide one cell of the layout was, in meters, at the normal density.
    pub cell_size: u32,
    /// How many cells across the layout was.
    pub layout_size: usize,
    /// The symbol set the maps were drawn with, as a file name beside this
    /// one. `None` for a dataset generated before it was copied there, which
    /// is a dataset nothing can turn back into a map.
    pub symbol_set: Option<String>,
    /// The table of labels the classes come out of, as a file name beside
    /// this one — see [`crate::label_set`]. `None` for a dataset with a class
    /// per symbol.
    pub labels: Option<String>,
    /// Whether the points layer says which way each point is turned, in two
    /// channels after the heatmaps — see [`crate::point_truth`]. Off for a
    /// dataset written before it did.
    pub point_angles: bool,
}

impl Classes {
    /// Reads a dataset's `classes.json`.
    ///
    /// By scanning for the keys rather than by parsing JSON: the file is one
    /// this crate writes, flat, and every value wanted here is a number or a
    /// string — which is a great deal less than a JSON dependency, in a crate
    /// whose job is to draw a map.
    pub fn read(path: &Path) -> Result<Classes, String> {
        let text = std::fs::read_to_string(path)
            .map_err(|e| format!("cannot read {}: {e}", path.display()))?;
        let missing = |key: &str| format!("{} names no {key}", path.display());
        let number = |key: &str| -> Result<f64, String> {
            value_of(&text, key)
                .and_then(|value| {
                    let digits: String = value
                        .chars()
                        .take_while(|c| c.is_ascii_digit() || *c == '.' || *c == '-' || *c == 'e')
                        .collect();
                    digits.parse().ok()
                })
                .ok_or_else(|| missing(key))
        };
        Ok(Classes {
            classes: number("classes")? as usize,
            // A file written before the lines had labels does not say.
            lines: number("lines").unwrap_or(0.0) as usize,
            // Nor one written before the points had them.
            points: number("points").unwrap_or(0.0) as usize,
            image_size: number("image_size")? as u32,
            resolution: number("resolution")?,
            // A dataset at one density, or written before they could differ.
            resolution_range: number("resolution_min")
                .ok()
                .zip(number("resolution_max").ok())
                .filter(|(low, high)| low < high),
            frame: number("frame")?,
            cell_size: number("cell_size")? as u32,
            layout_size: number("layout_size")? as usize,
            // The one field a file written before it existed does not have,
            // so its absence is an answer rather than an error.
            symbol_set: value_of(&text, "symbol_set")
                .and_then(|value| value.strip_prefix('"'))
                .and_then(|value| value.split('"').next())
                .map(str::to_string),
            labels: value_of(&text, "labels")
                .and_then(|value| value.strip_prefix('"'))
                .and_then(|value| value.split('"').next())
                .map(str::to_string),
            point_angles: value_of(&text, "point_angles").is_some_and(|v| v.starts_with("true")),
        })
    }
}

/// Whatever follows `"key":` in `text`, with the space after the colon
/// trimmed. The keys of this file are written once each and none of them is
/// a substring of another.
fn value_of<'a>(text: &'a str, key: &str) -> Option<&'a str> {
    let key = format!("\"{key}\":");
    text.find(&key)
        .map(|at| text[at + key.len()..].trim_start())
}

/// The pixels-per-meter a dataset's images were drawn at, out of the
/// `classes.json` written beside them.
///
/// A map file says nothing about the resolution it was rendered to — that is
/// a rendering choice, not a property of the map — so a label rebuilt from a
/// map file with [`crate::ground_truth::GroundTruth::from_map`], after its
/// `.bin` was left out of the folder, has nowhere else to read it from.
///
/// Reads the one field rather than the whole of [`Classes`]: a folder which
/// answers this question need not carry every other note for it to be a fair
/// answer.
pub fn resolution_of(dataset: &Path) -> Result<f64, String> {
    let path = dataset.join(CLASSES_FILE);
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("cannot read {}: {e}", path.display()))?;

    value_of(&text, "resolution")
        .and_then(|value| {
            value
                .split(|c: char| !(c.is_ascii_digit() || c == '.'))
                .next()
                .filter(|digits| !digits.is_empty())
                .and_then(|digits| digits.parse().ok())
        })
        .ok_or_else(|| format!("{} names no resolution", path.display()))
}

/// The density each map of a dataset was drawn at, by the name its map, image
/// and labels share, out of the [`RESOLUTIONS_FILE`] written beside them —
/// or `None` where there is no such file, which is a dataset whose maps were
/// all drawn at the one resolution `classes.json` gives.
pub fn resolutions_of(dataset: &Path) -> Result<Option<HashMap<String, f64>>, String> {
    let path = dataset.join(RESOLUTIONS_FILE);
    if !path.is_file() {
        return Ok(None);
    }
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("cannot read {}: {e}", path.display()))?;
    let mut read = HashMap::new();
    // The header first, then a map to a line.
    for (number, line) in text.lines().enumerate().skip(1) {
        if line.trim().is_empty() {
            continue;
        }
        let parsed = line.split_once(',').and_then(|(name, value)| {
            let value: f64 = value.trim().parse().ok()?;
            (value.is_finite() && value > 0.0).then(|| (name.trim().to_string(), value))
        });
        let Some((name, value)) = parsed else {
            return Err(format!(
                "{} line {}: {line:?} is not a map's name and its pixels per meter",
                path.display(),
                number + 1,
            ));
        };
        read.insert(name, value);
    }
    Ok(Some(read))
}

/// A string as a JSON one. A symbol name is whatever the symbol set called
/// it, which can be anything at all.
fn quoted(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_map_name_is_padded_to_the_size_of_the_dataset() {
        assert_eq!(map_name(0, 10), "map_001.omap");
        assert_eq!(map_name(9, 10), "map_010.omap");
        // Never narrower than three digits, and wider where it must be.
        assert_eq!(map_name(0, 2), "map_001.omap");
        assert_eq!(map_name(999, 1000), "map_1000.omap");
        // The map, its image and its labels share the stem.
        assert_eq!(map_stem(0, 10), "map_001");
    }

    #[test]
    fn every_image_of_a_dataset_is_the_layout_and_the_frame() {
        let settings = Settings {
            layout_size: 3,
            cell_size: 150,
            resolution: 3.0,
            frame: 50.0,
            ..Settings::default()
        };
        // 450 meters of layout and 50 on each side, three pixels to the meter.
        assert_eq!(settings.ground().width(), 550.0);
        assert_eq!(settings.image_size(), 1650);
    }

    /// What `write_classes` wrote is what `Classes::read` reads.
    #[test]
    fn a_classes_file_reads_back_as_what_was_written() {
        use crate::symbol_kinds::Entry;

        let catalogue = Catalogue {
            opaque_areas: vec![
                Entry {
                    index: 0,
                    id: 7,
                    code: "401".to_string(),
                    name: "Open land".to_string(),
                    turns: false,
                    symmetry: 1,
                },
                Entry {
                    index: 1,
                    id: 9,
                    code: "403".to_string(),
                    name: r#"Say "stop""#.to_string(),
                    turns: true,
                    symmetry: 1,
                },
            ],
            ..Catalogue::default()
        };
        let settings = Settings {
            layout_size: 2,
            cell_size: 60,
            resolution: 2.0,
            frame: 20.0,
            ..Settings::default()
        };
        let file = tempfile::NamedTempFile::new().expect("a temporary file");
        write_classes(file.path(), &catalogue, None, &settings, "ISOM_10k.omap")
            .expect("cannot write the classes");

        let read = Classes::read(file.path()).expect("cannot read them back");
        assert_eq!(read.classes, 2);
        assert_eq!(read.image_size, settings.image_size());
        assert_eq!(read.resolution, 2.0);
        assert_eq!(read.frame, 20.0);
        assert_eq!(read.cell_size, 60);
        assert_eq!(read.layout_size, 2);
        assert_eq!(read.symbol_set.as_deref(), Some("ISOM_10k.omap"));
    }

    /// A dataset with line labels names its line symbols, and one without
    /// them reads back as having none.
    #[test]
    fn a_classes_file_counts_the_lines_only_where_they_are_labelled() {
        use crate::symbol_kinds::Entry;

        let line = |index| Entry {
            index,
            id: index as i32,
            code: "305".to_string(),
            name: "Stream".to_string(),
            turns: false,
            symmetry: 1,
        };
        let catalogue = Catalogue {
            opaque_areas: vec![line(0)],
            lines: vec![line(1), line(2)],
            ..Catalogue::default()
        };
        let file = tempfile::NamedTempFile::new().expect("a temporary file");

        let labelled = Settings {
            line_labels: true,
            ..Settings::default()
        };
        write_classes(file.path(), &catalogue, None, &labelled, "set.omap").expect("cannot write");
        assert_eq!(Classes::read(file.path()).expect("read").lines, 2);

        write_classes(
            file.path(),
            &catalogue,
            None,
            &Settings::default(),
            "set.omap",
        )
        .expect("cannot write");
        assert_eq!(Classes::read(file.path()).expect("read").lines, 0);
        assert_eq!(Classes::read(file.path()).expect("read").points, 0);

        let catalogue = Catalogue {
            points: vec![line(3), line(4), line(5)],
            ..catalogue
        };
        let labelled = Settings {
            line_labels: true,
            point_labels: true,
            ..Settings::default()
        };
        write_classes(file.path(), &catalogue, None, &labelled, "set.omap").expect("cannot write");
        let read = Classes::read(file.path()).expect("read");
        assert_eq!((read.lines, read.points), (2, 3));
    }

    /// Line labels over a map with point symbols would leave them unlabelled.
    #[test]
    fn line_labels_are_refused_beside_overlays_they_cannot_label() {
        let dir = tempfile::tempdir().expect("a folder");
        let settings = Settings {
            line_labels: true,
            ..Settings::default()
        };
        let source = std::path::Path::new("tests/data/shapes.xmap");
        let result = create_dataset(source, dir.path(), &settings, |_, _| {});
        let message = result.err().expect("refused");
        assert!(message.contains("line labels"), "{message}");
    }

    /// Point labels need the lines labelled too, and nothing see-through
    /// drawn, which nothing would label.
    #[test]
    fn point_labels_are_refused_beside_what_they_cannot_label() {
        let dir = tempfile::tempdir().expect("a folder");
        let source = std::path::Path::new("tests/data/shapes.xmap");
        for (line_labels, transparent_areas, said) in [
            (false, 0.0, "line labels too"),
            (true, 0.5, "transparent areas"),
        ] {
            let settings = Settings {
                line_labels,
                point_labels: true,
                transparent_areas,
                ..Settings::default()
            };
            let result = create_dataset(source, dir.path(), &settings, |_, _| {});
            let message = result.err().expect("refused");
            assert!(message.contains(said), "{message}");
        }
    }

    /// A point symbol is never put on a line nor on another point symbol,
    /// and a good share of them are put right beside a line.
    #[test]
    fn a_point_symbol_keeps_off_the_lines_and_the_other_points() {
        let source = std::path::Path::new("symbols_sets/simple_ISSprOM_points.omap");
        let dir = tempfile::tempdir().expect("a folder");
        let settings = Settings {
            maps: 6,
            empty_sides: 0.2,
            transparent_areas: 0.0,
            point_symbols: 0.9,
            line_labels: true,
            point_labels: true,
            images: false,
            ..Settings::default()
        };
        let summary = create_dataset(source, dir.path(), &settings, |_, _| {})
            .expect("the dataset is generated");
        assert!(summary.drawn.points > 20, "{} points", summary.drawn.points);

        let (mut set, _) = xml_reader::read_xml_map(source).expect("the set");
        set.resolve_references();
        let catalogue = Catalogue::of(&set);
        let (mut beside, mut points) = (0, 0);
        for generated in &summary.written {
            let (mut map, _) = xml_reader::read_xml_map(&generated.map).expect("a map");
            map.resolve_references();
            let mut taken = Taken::default();
            let mut placed = Vec::new();
            for object in &map.objects {
                let Some(index) = object.symbol_index else {
                    continue;
                };
                if let Some(line) = catalogue.lines.iter().find(|e| e.index == index) {
                    taken.add_line(&object.coords, line_half_width(&map, line));
                } else if let Some(point) = catalogue.points.iter().find(|e| e.index == index) {
                    let at = Point::new(object.coords[0].x, object.coords[0].y);
                    placed.push((at, point_radius(&map, point)));
                }
            }
            for (at, radius) in &placed {
                points += 1;
                // A thousandth of a millimetre for the coordinates' rounding.
                let nearest = taken
                    .lines
                    .iter()
                    .map(|(line, half)| distance_to_polyline(*at, line) - half - radius)
                    .fold(f64::INFINITY, f64::min);
                assert!(
                    nearest >= LINE_GAP - 1e-3,
                    "a point {nearest} mm from a line"
                );
                if nearest <= LINE_GAP + NEAR_BAND + 1e-3 {
                    beside += 1;
                }
                for (other, reach) in &placed {
                    if other != at {
                        assert!((*at - *other).length() >= radius + reach + POINT_GAP - 1e-3);
                    }
                }
            }
        }
        assert!(
            beside * 4 >= points,
            "{beside} of {points} points beside a line"
        );
    }

    /// The lines of a generated map, each as its points, and the outlines
    /// of its cells whose ground draws a border, each as its points too.
    fn lines_and_bordered_outlines(
        map: &Map,
        catalogue: &Catalogue,
        bordered: &[bool],
    ) -> (Vec<Vec<Point>>, Vec<Vec<Point>>) {
        let points = |object: &Object| -> Vec<Point> {
            flatten(&object.coords)
                .into_iter()
                .flat_map(|part| part.points)
                .collect()
        };
        let (mut lines, mut outlines) = (Vec::new(), Vec::new());
        for object in &map.objects {
            let Some(index) = object.symbol_index else {
                continue;
            };
            if catalogue.lines.iter().any(|e| e.index == index) {
                lines.push(points(object));
            } else if let Some(at) = catalogue.opaque_areas.iter().position(|e| e.index == index) {
                if bordered[at] {
                    outlines.push(points(object));
                }
            }
        }
        (lines, outlines)
    }

    /// The generator's own answer to which of a set's opaque areas draw a
    /// border, in the order of its catalogue.
    fn bordered_areas(source: &Path) -> (Map, Catalogue, Vec<bool>) {
        let (mut map, _) = xml_reader::read_xml_map(source).expect("the set");
        map.resolve_references();
        let labels = LabelSet::beside(&map, source).expect("the labels");
        let mut catalogue = Catalogue::of(&map);
        catalogue.retain(|entry| labels.drawn(entry.index));
        let bordered = catalogue
            .opaque_areas
            .iter()
            .map(|area| {
                labels.outline_half_width(&map, area.index) > 0.0
                    || draws_a_border(&map, &map.symbols[area.index], 0)
            })
            .collect();
        (map, catalogue, bordered)
    }

    /// No line is drawn along the side of a cell whose ground draws a border
    /// round itself, where it would lie on that border: with a line on
    /// every side that may have one, not one runs along a bordered cell's
    /// outline. And no line through the cells goes into such a cell.
    #[test]
    fn no_line_lies_on_a_border() {
        let source = Path::new("symbols_sets/almost_ISSprOM.omap");
        let (_, catalogue, bordered) = bordered_areas(source);
        assert!(bordered.iter().any(|&b| b), "the set has bordered areas");
        assert!(bordered.iter().any(|&b| !b), "and some without");

        let dir = tempfile::tempdir().expect("a folder");
        let settings = Settings {
            maps: 12,
            empty_sides: 0.0,
            interior_lines: 0.6,
            transparent_areas: 0.0,
            point_symbols: 0.0,
            line_labels: true,
            images: false,
            ..Settings::default()
        };
        let summary = create_dataset(source, dir.path(), &settings, |_, _| {})
            .expect("the dataset is generated");
        assert!(summary.drawn.lines > 0 && summary.drawn.interior_lines > 0);

        for generated in &summary.written {
            let (mut map, _) = xml_reader::read_xml_map(&generated.map).expect("a map");
            map.resolve_references();
            let (lines, outlines) = lines_and_bordered_outlines(&map, &catalogue, &bordered);
            for line in &lines {
                for outline in &outlines {
                    // One point of a line on the outline is a side line
                    // ending at the bordered cell's corner; two are a line
                    // along it. And no point of one is inside the cell.
                    let on = line
                        .iter()
                        .filter(|&&p| distance_to_polyline(p, outline) < 1e-3)
                        .count();
                    assert!(on <= 1, "a line runs along a bordered cell's outline");
                    let mut closed = outline.clone();
                    closed.pop();
                    assert!(
                        !line
                            .iter()
                            .any(|&p| distance_to_polyline(p, outline) > 1e-3
                                && is_inside(&closed, p)),
                        "a line goes into a bordered cell"
                    );
                }
            }
        }
    }

    /// Lines through the cells are drawn where they are asked for, and only
    /// there: with every side left empty, every line of a map is one, and
    /// none of them runs along a side.
    #[test]
    fn lines_through_the_cells_cross_the_ground() {
        let source = Path::new("symbols_sets/simple_ISSprOM.omap");
        let dir = tempfile::tempdir().expect("a folder");
        let settings = Settings {
            maps: 30,
            empty_sides: 1.0,
            interior_lines: 1.0,
            transparent_areas: 0.0,
            point_symbols: 0.0,
            line_labels: true,
            images: false,
            ..Settings::default()
        };
        let summary = create_dataset(source, dir.path(), &settings, |_, _| {})
            .expect("the dataset is generated");
        assert_eq!(summary.drawn.lines, 0);
        assert!(
            summary.drawn.interior_lines >= 4,
            "{} lines through the cells",
            summary.drawn.interior_lines
        );

        // Never along each other: two lines may cross, as often as they
        // meet, and a crossing is a short stretch of one near the other; but
        // no long stretch of one lies on the other.
        let (set, catalogue, bordered) = bordered_areas(source);
        drop(set);
        for generated in &summary.written {
            let (mut map, _) = xml_reader::read_xml_map(&generated.map).expect("a map");
            map.resolve_references();
            let (lines, _) = lines_and_bordered_outlines(&map, &catalogue, &bordered);
            for (a, one) in lines.iter().enumerate() {
                for other in &lines[a + 1..] {
                    // The longest stretch of one within 0.2 mm of the
                    // other, walked in steps of a twentieth of a mm.
                    let (mut run, mut longest) = (0.0, 0.0_f64);
                    for pair in one.windows(2) {
                        let length = (pair[1] - pair[0]).length();
                        let steps = (length / 0.05).ceil().max(1.0);
                        for step in 0..steps as usize {
                            let at = pair[0] + (pair[1] - pair[0]) * ((step as f64 + 0.5) / steps);
                            if distance_to_polyline(at, other) < 0.2 {
                                run += length / steps;
                                longest = longest.max(run);
                            } else {
                                run = 0.0;
                            }
                        }
                    }
                    // A crossing at an angle `a` is 0.4 / sin a mm of it:
                    // 1.5 mm is one at fifteen degrees, flatter than
                    // `Layout::leg` lets one through, with room for the
                    // wandering. Running along each other is far more.
                    assert!(longest < 1.5, "{longest} mm of two lines lie on each other");
                }
            }
        }

        let none = Settings {
            interior_lines: 0.0,
            ..settings
        };
        let summary =
            create_dataset(source, dir.path(), &none, |_, _| {}).expect("the dataset is generated");
        assert_eq!(summary.drawn.interior_lines, 0);
    }

    /// A set with a table of labels beside it is labelled by the table: the
    /// table goes into the dataset beside the set, `classes.json` names it
    /// and lists its classes, and the symbols it keeps for parts of others
    /// are never drawn on their own.
    #[test]
    fn a_set_with_a_table_is_labelled_by_the_table() {
        let source = std::path::Path::new("symbols_sets/almost_ISSprOM.omap");
        let dir = tempfile::tempdir().expect("a folder");
        let settings = Settings {
            layout_size: 3,
            cell_size: 30,
            maps: 2,
            transparent_areas: 0.0,
            line_labels: true,
            point_labels: true,
            ..Settings::default()
        };
        let summary = create_dataset(source, dir.path(), &settings, |_, _| {})
            .expect("the dataset is generated");
        let read = Classes::read(&dir.path().join(CLASSES_FILE)).expect("classes.json");
        assert_eq!((read.classes, read.lines, read.points), (33, 41, 29));
        assert_eq!(read.labels.as_deref(), Some("almost_ISSprOM.labels.json"));
        assert!(read.point_angles);
        assert!(dir.path().join("almost_ISSprOM.labels.json").is_file());

        let fill = summary.labels.parts(
            summary
                .catalogue
                .opaque_areas
                .iter()
                .find(|e| e.code == "521")
                .expect("a building is drawn")
                .index,
        );
        assert_eq!(fill.len(), 2);
        for generated in &summary.written {
            let (mut map, _) = xml_reader::read_xml_map(&generated.map).expect("a map");
            map.resolve_references();
            for object in &map.objects {
                let index = object.symbol_index.expect("a symbol");
                assert!(summary.labels.drawn(index), "{}", map.symbols[index].code());
            }
        }
    }

    /// A line is only ever drawn where it can be seen: a strip of green
    /// vegetation goes under the white of a forest, and is not drawn beside
    /// one.
    #[test]
    fn a_line_shows_up_over_the_ground_it_may_be_drawn_on() {
        let (mut map, _) =
            xml_reader::read_xml_map(std::path::Path::new("symbols_sets/almost_ISSprOM.omap"))
                .expect("the set");
        map.resolve_references();
        let catalogue = Catalogue::of(&map);
        let over = lines_over(&map, &catalogue);
        let at = |list: &[Entry], code: &str| list.iter().position(|e| e.code == code).unwrap();
        let forest = at(&catalogue.opaque_areas, "405");
        let open_land = at(&catalogue.opaque_areas, "401");
        let narrow = at(&catalogue.lines, "406.2");
        let path = at(&catalogue.lines, "506");
        assert!(!over[forest].contains(&narrow));
        assert!(over[open_land].contains(&narrow));
        assert!(over[forest].contains(&path));
    }

    /// A dataset generated before the set was copied in says nothing about
    /// one, which is an answer rather than a file which cannot be read.
    #[test]
    fn a_classes_file_without_a_symbol_set_says_so() {
        let file = tempfile::NamedTempFile::new().expect("a temporary file");
        std::fs::write(
            file.path(),
            "{\n  \"classes\": 3,\n  \"image_size\": 100,\n  \"resolution\": 3,\n  \
             \"frame\": 50,\n  \"cell_size\": 150,\n  \"layout_size\": 3\n}\n",
        )
        .expect("a file to read");
        let read = Classes::read(file.path()).expect("cannot read it");
        assert_eq!(read.classes, 3);
        assert_eq!(read.symbol_set, None);
    }

    /// The symbol set is copied in under its own name, and copying a file
    /// which is already there leaves it alone rather than truncating it.
    #[test]
    fn the_symbol_set_is_copied_in_under_its_own_name() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let source = dir.path().join("ISOM_10k.omap");
        std::fs::write(&source, b"<map/>").expect("a file to copy");

        let into = dir.path().join("dataset");
        std::fs::create_dir(&into).expect("the dataset folder");
        assert_eq!(
            copy_symbol_set(&source, &into).expect("cannot copy it"),
            "ISOM_10k.omap"
        );
        assert_eq!(
            std::fs::read(into.join("ISOM_10k.omap")).expect("the copy"),
            b"<map/>"
        );

        // Generating a dataset into the folder the set is already in.
        assert_eq!(
            copy_symbol_set(&into.join("ISOM_10k.omap"), &into).expect("cannot copy it"),
            "ISOM_10k.omap"
        );
        assert_eq!(
            std::fs::read(into.join("ISOM_10k.omap")).expect("the copy"),
            b"<map/>"
        );
    }

    #[test]
    fn a_symbol_name_goes_into_json_as_one() {
        assert_eq!(quoted(r#"Say "stop""#), r#""Say \"stop\"""#);
        assert_eq!(quoted("a\tb"), r#""a\tb""#);
    }

    /// The resolution `write_classes` wrote is the resolution `resolution_of`
    /// reads back, whole or fractional.
    #[test]
    fn resolution_of_reads_back_what_write_classes_wrote() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        let catalogue = Catalogue::default();
        for resolution in [3.0, 2.5] {
            let settings = Settings {
                resolution,
                ..Settings::default()
            };
            write_classes(
                &dir.path().join(CLASSES_FILE),
                &catalogue,
                None,
                &settings,
                "symbols.ocd",
            )
            .expect("classes.json writes");
            assert_eq!(resolution_of(dir.path()), Ok(resolution));
        }
    }

    /// A folder with no `classes.json` has no resolution to read, which is
    /// what a dataset not generated with `--just-opaque-areas` looks like.
    #[test]
    fn resolution_of_a_folder_without_classes_json_is_refused() {
        let dir = tempfile::tempdir().expect("a temporary folder");
        assert!(resolution_of(dir.path()).is_err());
    }
}
